from collections import deque
graph = {0: [1, 2], 1: [3], 2: [], 3: []}
q = deque([0])
seen = {0}
order = []
while q:
    x = q.popleft()
    order.append(x)
    for y in graph[x]:
        if y not in seen:
            seen.add(y)
            q.append(y)
print("BFS:", order)

