def cmp(a, b):
    return -1 if a + b > b + a else (1 if a + b < b + a else 0)
parts = sorted(map(str, nums), key=cmp_to_key(cmp))
print("最大数:", "".join(parts))

from functools import cache
@cache
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
print("fib(10):", fib(10))
print("缓存信息:", fib.cache_info())

