tree = {1: [2, 3], 2: [], 3: []}
ans = 0
def dfs(u, depth):
    global ans
    ans = max(ans, depth)
    for v in tree[u]:
        dfs(v, depth + 1)
dfs(1, 1)
print("最大深度:", ans)

def max_depth(tree):
    ans = 0
    def dfs(u, depth):
        nonlocal ans
        ans = max(ans, depth)
        for v in tree[u]:
            dfs(v, depth + 1)
    dfs(1, 1)
    return ans
print("深度:", max_depth({1: [2], 2: [3], 3: []}))

