def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)
print("fact5:", fact(5))

class Solution:
    def twoSum(self, nums, target):
        pos = {}
        for i, x in enumerate(nums):
            if target - x in pos:
                return [pos[target - x], i]
            pos[x] = i
print("答案:", Solution().twoSum([2, 7, 11], 9))

