from collections import deque
grid = [[0, 0], [1, 0]]
q = deque([(0, 0, 0)])
seen = {(0, 0)}
while q:
    r, c, d = q.popleft()
    if (r, c) == (1, 1):
        print("距离:", d)
        break
    for dr, dc in [(1, 0), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 2 and 0 <= nc < 2 and grid[nr][nc] == 0 and (nr, nc) not in seen:
            seen.add((nr, nc)); q.append((nr, nc, d + 1))

from functools import cache
@cache
def ways(n):
    if n <= 1:
        return 1
    return ways(n - 1) + ways(n - 2)
print("爬楼梯:", ways(5))
